mapper.update:
UPDATE SMS SET

    SMS_STOPTIME = #{smsStoptime,jdbcType=TIMESTAMP},

SMS_UPDATETIME = SYSDATE, SMS_SERVICESTATE = #{smsServicestate,jdbcType=CHAR}, SMS_CPU = 0, SMS_RAM = 0, SMS_THREADS = 0, SMS_PID = NULL
WHERE SMS_SERVICENAME = #{smsServicename,jdbcType=VARCHAR}
AND SMS_SERVICEIP = #{smsServiceip,jdbcType=VARCHAR}

update SMS
set SMS_CPU_THRESHOLD     = #{smsCpuThreshold,jdbcType=INTEGER},
    SMS_RAM_THRESHOLD     = #{smsRamThreshold,jdbcType=INTEGER},
    SMS_THREADS_THRESHOLD = #{smsThreadsThreshold,jdbcType=INTEGER}
where SMS_SERVICENAME = #{smsServicename,jdbcType=VARCHAR}
  and SMS_SERVICEIP = #{smsServiceip,jdbcType=VARCHAR}
